//#region src/lib/admin/permissions.ts
function hasAnyRole(auth, roles) {
	return auth.roles.some((r) => roles.includes(r));
}
function isReceptionOrAdmin(auth) {
	return hasAnyRole(auth, ["admin", "reception"]);
}
function canOverrideAppointmentRules(auth) {
	return hasAnyRole(auth, ["admin", "reception"]);
}
//#endregion
export { isReceptionOrAdmin as n, canOverrideAppointmentRules as t };
